import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`roofing-bid`,heroTitle:`Turn roofing plans into winning bids`,heroSubtitle:`Perplexity Computer analyzes your uploaded roofing plans, sizes materials and labor, and builds a detailed bid automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your roofing plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded roofing plans, inspection notes, or a scope package. Build a complete roofing bid. (1) Extract roof areas, pitch, system type, tear-off scope, flashing, accessories, and site constraints from the uploaded files. (2) Estimate material quantities, waste factors, labor, dumpsters, and subcontractor work where needed. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, field-verification items, and change-order risks that should be called out in the bid. (5) Deliver a detailed roofing bid with line-item pricing, scope summary, and next steps that is ready for the client.`,heroOverlaySteps:[`Extracting roof areas, system details, tear-off scope, and site constraints from your files`,`Sizing materials, waste factors, labor, and supporting services`,`Building pricing options with assumptions, alternates, and exclusions`,`Client-ready roofing bid with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, inspection notes, and scope package`,`Designing an agent to organize materials, waste factors, and labor assumptions`,`Configuring bid logic for alternates, exclusions, and change-order risk`,`Preparing a detailed roofing bid with line items and next steps`],featureSectionTitle:`From roofing plans to bid-ready pricing`,featureCardTitles:[`Connects to your estimating workflow`,`Bids built for scope clarity and margin`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, takeoffs, and internal review workflows stay connected so bidding and revisions move faster.`,`Material counts. Waste assumptions. Labor. Alternates. Computer gives your team a roofing bid draft that is ready for client review.`],capabilitySectionTitle:`Your estimating desk, on autopilot`,capabilitySectionSubtitle:`Upload the plans, get back a roofing bid built around the real roof system and scope.`,capabilityCards:[{title:`Plan & Takeoff Analysis`,description:`Computer can extract roof areas, pitch, tear-off scope, flashing, accessories, and system details from plans and inspection documents.`},{title:`Materials & Labor Planning`,description:`Computer can size shingles or membranes, waste factors, labor, dumpsters, and supporting work so the bid reflects the actual project.`},{title:`Pricing & Alternates`,description:`Computer can build pricing options, assumptions, and alternates so you can present a clearer bid with less manual spreadsheet work.`},{title:`Connect Your Tools`,description:`Computer can keep bid drafts organized across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred materials, markup rules, and estimate structure across sessions so bids stay consistent.`},{title:`Change-Order Protection`,description:`Computer can surface scope gaps and field-verification items early so your team can protect margin before the client signs.`}]});export{t as default};
